$ErrorActionPreference='Stop'
$base='C:\Users\clclc\BusinessProject'
$output=Join-Path $base 'Rineya-Worktree-Audit-20261009\supa-audit.json'
$j=Get-Content -LiteralPath $output -Raw | ConvertFrom-Json
$hybrid=$j.repositories | Where-Object name -eq 'SupaExperiment-hybrid-memory-v1'
$paths=@(git -c core.longpaths=true -C $hybrid.path ls-files --others --ignored --exclude-standard)
$facts=@(foreach($rel in $paths) { $i=Get-Item -LiteralPath (Join-Path $hybrid.path $rel) -Force; [pscustomobject]@{path=$rel;bytes=$i.Length;modifiedUtc=$i.LastWriteTimeUtc.ToString('o');attributes="$($i.Attributes)"} })
$hybrid.ignored=$facts
$hybrid.ignoredCount=$facts.Count
$hybrid.ignoredBytes=($facts | Measure-Object bytes -Sum).Sum
$hybrid.ignoredTopLevel=@($facts | Group-Object {($_.path -split '/')[0]} | ForEach-Object {[pscustomobject]@{name=$_.Name;count=$_.Count;bytes=($_.Group | Measure-Object bytes -Sum).Sum}} | Sort-Object bytes -Descending)
$hybrid.largestIgnored=@($facts | Sort-Object bytes -Descending | Select-Object -First 25)
$scientific=@($facts | Where-Object {$_.path -notmatch '/(plot-dependencies|test_dependencies|software_qualification|software)/' -and $_.path -notmatch '/__pycache__/' -and $_.path -notmatch '\.pyc$'})
$manifest=@(foreach($f in $scientific) { [pscustomobject]@{path=$f.path;bytes=$f.bytes;sha256=(Get-FileHash -LiteralPath (Join-Path $hybrid.path $f.path) -Algorithm SHA256).Hash.ToLower()} })
[pscustomobject]@{sourceRoot=$hybrid.path;branchHead=$hybrid.head;preservationRequired=$true;scientificIgnoredFiles=$manifest;fileCount=$manifest.Count;bytes=($manifest | Measure-Object bytes -Sum).Sum;exclusion='Reconstructible plot/test dependencies and synthetic software fixture output omitted from this manifest. Preserve entire ignored tree if scope cannot be independently established.'} | ConvertTo-Json -Depth 6 | Set-Content -LiteralPath (Join-Path $base 'Rineya-Worktree-Audit-20261009\supa-hybrid-ignored-scientific-manifest.json') -Encoding UTF8
$decisions=@(
 [pscustomobject]@{path='SupaExperiment';disposition='KEEP_PRIMARY';reason='44 untracked historical evaluation/data/output files (11,252,875 bytes), plus ignored adapter/raw output files and 4.59GB CUDA environment; initialized pinned model submodule. No primary-checkout deletion.'},
 [pscustomobject]@{path='SupaExperiment-hybrid-memory-v1';disposition='RETIRE_AFTER_IGNORED_ARTIFACT_ARCHIVE';reason='Clean historical worktree; exact tip b1813444 is covered by archive/supa-a1.1-hybrid-memory-architecture-v1-stage1-complete-2026-09-09. STATUS and DECISION explicitly complete Stage I and stop fixed study, negative promotion result. Initialized submodules absent. Ignored tree includes all trained A1-A4 adapters, DEV/native adapters, consumed execution ledger, full raw evaluation/recovery outputs, and immutable bank; Git tag does not preserve these. Archive all scientific ignored files with byte/hash verification first; runtime dependencies can be regenerated.';evidencePaths=@('experiments/hybrid_memory_architecture_v1/reports/STATUS.md','experiments/hybrid_memory_architecture_v1/reports/DECISION.md','experiments/hybrid_memory_architecture_v1/reports/COMPLETION_AUDIT.md');archiveTag='archive/supa-a1.1-hybrid-memory-architecture-v1-stage1-complete-2026-09-09';exactHead='b1813444f76f214fed627af4bebe39a9354b721c'},
 [pscustomobject]@{path='SupaExperiment-matched-mlp-m2-readiness-v1';disposition='KEEP_DIRTY_ACTIVE_SUCCESSOR';reason='Two tracked edits and 15 untracked new source, proposal, source-lock, receipt and fixture-test files. Native M2 stays blocked, but unreleased offline integration and owner dependencies are current. Commit/tag of HEAD alone would lose working changes.';evidencePaths=@('experiments/matched_mlp_m2_v1/readiness/STATUS.json','experiments/matched_mlp_m2_v1/readiness/README.md')},
 [pscustomobject]@{path='SupaExperiment-matched-mlp-shipping-v1';disposition='KEEP_ORIGINAL_M1_OWNER_DEPENDENCY';reason='Clean and remote-synchronized; initialized immutable model submodule. Readiness README lines 116-120 and source audit require this exact original shipping branch/worktree as M1 owner/source. Later external attempt03 PASS_NATIVE_MECHANICS_ONLY is informational in RINQ, not permission to retire source owner. Preserve branch and checkout while current M2/RINQ dependencies remain.';evidencePaths=@('experiments/matched_mlp_shipping_v1/README.md','../SupaExperiment-matched-mlp-m2-readiness-v1/experiments/matched_mlp_m2_v1/readiness/README.md')},
 [pscustomobject]@{path='SupaExperiment-nonrecurrent-adaptation-v1';disposition='KEEP_DIRTY_CURRENT_RESEARCH_OWNER';reason='Five tracked docs/status changes and 27 untracked research-source/protocol files. STATUS contains current 2026-10-07 blocked goal with standing user approval, genuine external control/full-profile feasibility dependency, and goal_complete=false. 3.18GB ignored environment, initialized model submodule; no obsolete finding.';evidencePaths=@('experiments/nonrecurrent_adaptation_v1/STATUS.json')},
 [pscustomobject]@{path='SupaExperiment-rineya-quality-v1';disposition='PRESERVE_LOCAL_ONLY_COMMITS_THEN_KEEP_CURRENT_RINQ';reason='Clean, no ignored files or initialized submodule. Seven local-only commits at ea0a1a1; no containing remote branch or tag. STATUS dated 2026-10-05 reports OFFLINE_IMPLEMENTATION_NATIVE_QUALITY_BLOCKED, and external owner attempt03 pass remains unenrolled. Preserve via remote branch or archive tag before any checkout cleanup; active RINQ source is not obsolete.';exactHead='ea0a1a1053f4958adad2f9e016a087d4eab7c23e';evidencePaths=@('experiments/rineya_quality_v1/STATUS.json','experiments/rineya_quality_v1/README.md')},
 [pscustomobject]@{path='RineyaArchitecture';disposition='KEEP_INDEPENDENT_PRIMARY';reason='Only registered worktree; clean main at 2d50f33c, matches origin/main. Eighteen cached remote refs include benchmark, EAM, looped-flow, FGP, baseline, SWA and programme tracks. These are remote-only histories, not redundant local worktrees. README says development mechanics qualified; pretrained experiments blocked by execution access; closure/obsolescence not proven. No ignored assets.'},
 [pscustomobject]@{path='rineya-dataset-retention-records';disposition='KEEP_EVIDENCE_REPOSITORY_AND_UNPUBLISHED_RECEIPTS';reason='Only registered worktree; master matches origin/master but 135 untracked logs/journals/weight-deletion receipts (570,275 bytes), plus 12,829,082,577 ignored bytes. Includes CLOCKFIX checkpoint tensors (~6.22GB), TRISKILL checkpoint tensors and unique trained_C backup (~5.03GB), tokenizer duplicates and input zip. README states trained outputs not reproducible, preserved as private-vault deltas; old verification covers five historical runs, not all current tensors. Git tags/releases would not preserve ignored weights or untracked receipts. No deletion without separate artifact backup verification.';evidencePaths=@('README.md','TRAINED_TENSOR_BACKUP_VERIFY_20260926.json','triskill001-20260926/TRAIN_STATUS.json')}
)
$j | Add-Member -NotePropertyName recommendations -NotePropertyValue $decisions -Force
$optional=@('research/recurrence-atlas-review-v2','research/supa-a1.1-abstention-calibration-v1','research/supa-a1.1-positional-abstention-a07-v1','research/supa-a1.1-recurrence-a04-per-hook-gates-v1','research/supa-a1.1-recurrence-a05-gate-lr-v1','research/supa-a1.1-recurrent-normalized-gate-lr-v1','research/supa-a1.1-temperature-surface-v1')
$branchDecisions=@(foreach($b in ($j.repositories | Where-Object name -eq 'SupaExperiment').branches) { $short=$b.ref -replace '^refs/heads/',''; $disposition='KEEP_REF_NO_WORKTREE_SPACE_GAIN'; if($short -in $optional) {$disposition='OPTIONAL_RETIRED_LOCAL_REF_REMOVAL_AFTER_REMOTE_TAG_VERIFICATION'}; if($short -eq 'a06-work') {$disposition='OPTIONAL_REDUNDANT_LOCAL_REF_REMOVAL_REMOTE_DESCENDANT_PRESERVES_HEAD'}; if($short -eq 'codex/rineya-quality-v1') {$disposition='PUBLISH_LOCAL_ONLY_HEAD_BEFORE_ANY_RETIREMENT'}; if($short -eq 'research/supa-a1.1-hybrid-memory-architecture-v1') {$disposition='RETIRED_ARCHIVED_HEAD_KEEP_ARTIFACTS_BEFORE_CHECKOUT_REMOVAL'}; [pscustomobject]@{branch=$short;head=$b.head;disposition=$disposition;exactTags=$b.exactTags;containingRemoteRefs=$b.remoteCoverage;commitsNotReachableFromRemoteBranches=$b.commitsNotReachableFromRemoteRefs} })
$j | Add-Member -NotePropertyName supaLocalBranchDisposition -NotePropertyValue $branchDecisions -Force
$j | Add-Member -NotePropertyName limits -NotePropertyValue @('Root agent separately verified/fetched live remotes. This scan did not fetch, push, tag, change tracked files, train, or remove any repository/worktree.','All Supa local heads, remote refs and tags were recorded with exact containment. No branch was declared obsolete based only on age.','Git core.longpaths was enabled per command to inventory the hybrid ignored runtime tree without changing config; initial warning pseudo-paths were replaced by complete actual file facts.','Model submodule directories were inspected only for git identity/status/ignored names; model tensor contents were not read.','Primary and dirty checkouts, current owner/source dependencies, and independent evidence repositories are retained. Candidate hybrid requires verified artifact preservation even though committed source already has archive tag.','External research-record directories and private-vault storage are outside this delegated repository scope and are audited by the root agent separately.') -Force
$j | ConvertTo-Json -Depth 14 | Set-Content -LiteralPath $output -Encoding UTF8
[pscustomobject]@{hybridIgnoredFiles=$facts.Count;hybridIgnoredBytes=$hybrid.ignoredBytes;scientificFiles=$manifest.Count;scientificBytes=($manifest | Measure-Object bytes -Sum).Sum;recommendations=$decisions.Count;report=$output} | ConvertTo-Json
